PREFIX dbo: <http://dbpedia.org/ontology/>

SELECT ?film ?director ?deathDate
WHERE {
  VALUES ?film { 
    <http://dbpedia.org/resource/Haiducii_(film)> 
    <http://dbpedia.org/resource/My_Wife's_Best_Friend>
  }
  ?film dbo:director ?director .
  ?director dbo:deathDate ?deathDate .
}
ORDER BY ?deathDate
LIMIT 100

